@echo off
setlocal
cd /d "%~dp0"
if not exist "target\debug\project-rl.exe" (
  echo Compilez d'abord avec cargo build --locked.
  pause
  exit /b 1
)
"target\debug\project-rl.exe" --essai-egouts %*

@echo off
setlocal
cd /d "%~dp0"
if not exist "target\debug\project-rl.exe" (
  echo Compilez d'abord avec cargo build --locked.
  pause
  exit /b 1
)
"target\debug\project-rl.exe" --essai-population-prison

@echo off
cd /d "%~dp0"
cargo build --locked --bin project-rl --features dialogue-audio-trial
if errorlevel 1 (
  pause
  exit /b 1
)
start "Project RL - Essai dialogue terminal 03" "%~dp0target\debug\project-rl.exe" --essai-dialogue-terminal

@echo off
setlocal
cd /d "%~dp0"
if not exist "target\debug\examples\handcrafted_camp_full_review.exe" (
    cargo build --locked --example handcrafted_camp_full_review
    if errorlevel 1 (
        pause
        exit /b 1
    )
)
"target\debug\examples\handcrafted_camp_full_review.exe"
